"""The notebooks are generated by scripts/make_notebooks.py: check the files exist, parse, contain valid Python and shipped with outputs."""
import ast
import json
from pathlib import Path

from scripts import make_notebooks as mk

NB_DIR = Path(__file__).parents[1] / "notebooks"


def _code(nb):
    for c in nb["cells"]:
        if c["cell_type"] == "code":
            yield "".join(c["source"])


def test_generator_covers_the_nine_notebooks_and_cells_are_valid_python():
    assert len(mk.NOTEBOOKS) == 9
    for name, cells in mk.NOTEBOOKS.items():
        nbk = mk.nb(cells)
        for src in _code(nbk):
            lines = [ln for ln in src.splitlines() if not ln.lstrip().startswith("%")]       # drop IPython magics
            ast.parse("\n".join(lines), filename=name)


def test_committed_notebooks_match_generator_and_have_outputs():
    for name, cells in mk.NOTEBOOKS.items():
        p = NB_DIR / f"{name}.ipynb"
        assert p.exists(), name
        nbk = json.loads(p.read_text(encoding="utf-8"))
        want = [c["source"] for c in mk.nb(cells)["cells"] if c["cell_type"] == "code"]
        have = [c["source"] for c in nbk["cells"] if c["cell_type"] == "code"]
        assert want == have, f"{name} is out of date: run python scripts/make_notebooks.py --run"
        codes = [c for c in nbk["cells"] if c["cell_type"] == "code"]
        assert any(c.get("outputs") for c in codes), f"{name} has no outputs"
        assert not any(o.get("output_type") == "error" for c in codes for o in c.get("outputs", []))
